<?php
require_once __DIR__.'/../../includes/functions.php';require_admin();$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$status=(string)($_POST['status']??'');$notes=trim((string)($_POST['admin_notes']??''));if(!$id||!in_array($status,['pending','approved','rejected','completed','cancelled'],true))$error='Invalid consultation update.';else{$pdo=db();$pdo->beginTransaction();try{$stmt=$pdo->prepare('SELECT preferred_date,preferred_time,status,name,email,consultation_type FROM consultations WHERE id=? FOR UPDATE');$stmt->execute([$id]);$old=$stmt->fetch();if(!$old)throw new RuntimeException('Consultation not found.');$pdo->prepare('UPDATE consultations SET status=?,admin_notes=? WHERE id=?')->execute([$status,$notes?:null,$id]);if(in_array($status,['rejected','cancelled'],true))$pdo->prepare('UPDATE consultation_slots SET consultation_id=NULL WHERE available_date=? AND available_time=? AND consultation_id=?')->execute([$old['preferred_date'],$old['preferred_time'],$id]);$pdo->commit();if($old['status']!==$status)send_business_email($old['email'],'Yucca Fabrics consultation update',"Hello {$old['name']},\n\nYour {$old['consultation_type']} consultation request for {$old['preferred_date']} at {$old['preferred_time']} is now marked {$status}.\n\n{$notes}\n\nYucca Fabrics");$notice='Consultation updated.';}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();$error=$exception instanceof RuntimeException?$exception->getMessage():'Consultation update failed.';error_log('Consultation update failed: '.$exception->getMessage());}}}
$rows=db()->query('SELECT * FROM consultations ORDER BY preferred_date DESC,preferred_time DESC LIMIT 150')->fetchAll();$adminTitle='Consultations · Yucca Fabrics';require __DIR__.'/../../includes/admin-header.php';
?>
<h1 class="font-serif text-4xl">Consultations</h1><?php if($error||$notice): ?><p class="mt-4 rounded p-3 text-sm <?= $error?'bg-red-50 text-red-800':'bg-green-50 text-green-800' ?>"><?= e($error?:$notice) ?></p><?php endif; ?><div class="mt-6 space-y-4"><?php foreach($rows as $row): ?><article class="grid gap-5 bg-white p-5 lg:grid-cols-[1fr_1fr]"><div><p class="font-serif text-2xl"><?= e($row['consultation_type']) ?></p><p class="mt-2 text-sm"><?= e($row['name']) ?> · <?= e($row['email']) ?> · <?= e($row['phone']) ?></p><p class="mt-2 text-sm text-gray-600"><?= e($row['property_type']) ?> in <?= e($row['location']) ?> · <?= e($row['method']) ?></p><p class="mt-2 text-sm font-semibold"><?= e(date('M j, Y',strtotime($row['preferred_date']))) ?> · <?= e(date('g:i A',strtotime($row['preferred_time']))) ?></p><p class="mt-3 whitespace-pre-line text-sm text-gray-600"><?= e($row['description']) ?></p><?php if($row['budget']): ?><p class="mt-2 text-xs">Budget: <?= e($row['budget']) ?></p><?php endif; ?></div><form method="post" class="grid content-start gap-3"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><label class="text-sm">Status<select name="status" class="form-control mt-1"><?php foreach(['pending','approved','rejected','completed','cancelled'] as $status): ?><option value="<?= e($status) ?>" <?= $row['status']===$status?'selected':'' ?>><?= e(ucfirst($status)) ?></option><?php endforeach; ?></select></label><label class="text-sm">Internal / customer note<textarea class="form-control mt-1" name="admin_notes" rows="3"><?= e($row['admin_notes']??'') ?></textarea></label><button class="w-fit rounded-full bg-forest px-5 py-2 text-sm text-white">Save consultation</button></form></article><?php endforeach; ?></div>
<?php require __DIR__.'/../../includes/admin-footer.php'; ?>
